data ProducerAccessMode
  = Shared | Exclusive | WaitForExclusive | ExclusiveWithFencing
  deriving stock (Prelude.Show, Prelude.Eq, Prelude.Ord)
instance Data.ProtoLens.MessageEnum ProducerAccessMode where
  maybeToEnum 0 = Prelude.Just Shared
  maybeToEnum 1 = Prelude.Just Exclusive
  maybeToEnum 2 = Prelude.Just WaitForExclusive
  maybeToEnum 3 = Prelude.Just ExclusiveWithFencing
  maybeToEnum _ = Prelude.Nothing
  showEnum Shared = "Shared"
  showEnum Exclusive = "Exclusive"
  showEnum WaitForExclusive = "WaitForExclusive"
  showEnum ExclusiveWithFencing = "ExclusiveWithFencing"
  readEnum k
    | (Prelude.==) k "Shared" = Prelude.Just Shared
    | (Prelude.==) k "Exclusive" = Prelude.Just Exclusive
    | (Prelude.==) k "WaitForExclusive" = Prelude.Just WaitForExclusive
    | (Prelude.==) k "ExclusiveWithFencing"
    = Prelude.Just ExclusiveWithFencing
    | Prelude.otherwise
    = (Prelude.>>=) (Text.Read.readMaybe k) Data.ProtoLens.maybeToEnum
instance Prelude.Bounded ProducerAccessMode where
  minBound = Shared
  maxBound = ExclusiveWithFencing
instance Prelude.Enum ProducerAccessMode where
  toEnum k__
    = Prelude.maybe
        (Prelude.error
           ((Prelude.++)
              "toEnum: unknown value for enum ProducerAccessMode: "
              (Prelude.show k__)))
        Prelude.id (Data.ProtoLens.maybeToEnum k__)
  fromEnum Shared = 0
  fromEnum Exclusive = 1
  fromEnum WaitForExclusive = 2
  fromEnum ExclusiveWithFencing = 3
  succ ExclusiveWithFencing
    = Prelude.error
        "ProducerAccessMode.succ: bad argument ExclusiveWithFencing. This value would be out of bounds."
  succ Shared = Exclusive
  succ Exclusive = WaitForExclusive
  succ WaitForExclusive = ExclusiveWithFencing
  pred Shared
    = Prelude.error
        "ProducerAccessMode.pred: bad argument Shared. This value would be out of bounds."
  pred Exclusive = Shared
  pred WaitForExclusive = Exclusive
  pred ExclusiveWithFencing = WaitForExclusive
  enumFrom = Data.ProtoLens.Message.Enum.messageEnumFrom
  enumFromTo = Data.ProtoLens.Message.Enum.messageEnumFromTo
  enumFromThen = Data.ProtoLens.Message.Enum.messageEnumFromThen
  enumFromThenTo = Data.ProtoLens.Message.Enum.messageEnumFromThenTo
instance Data.ProtoLens.FieldDefault ProducerAccessMode where
  fieldDefault = Shared
instance Control.DeepSeq.NFData ProducerAccessMode where
  rnf x__ = Prelude.seq x__ ()
